const customerId = String($json.customer_id ?? '').trim().toUpperCase();
if (!/^[A-Z0-9][A-Z0-9_-]{1,63}$/.test(customerId)) {
  throw new Error('customer_id is required and invalid');
}
return { json: { customer_id: customerId, started_at_ms: Date.now() } };

const input = $('Validate Customer ID').first().json;
const row = $input.first().json ?? {};
const customerFound = Boolean(row.customer_id);
const subscriptionFound = customerFound && row.plan !== null && row.plan !== undefined;

return [{ json: {
  found: subscriptionFound,
  customer_found: customerFound,
  subscription: subscriptionFound ? {
    customer_id: row.customer_id,
    account_status: row.account_status,
    plan: row.plan,
    payment_status: row.payment_status,
    activation_status: row.activation_status,
    started_at: row.started_at
  } : null,
  latency_ms: Date.now() - input.started_at_ms
} }];
